import type { Hero } from '../types';

const now = new Date().toISOString();

function hero(
  h: Omit<Hero, 'created_at' | 'updated_at' | 'approved_at'> & {
    approved_at?: string | null;
  }
): Hero {
  return {
    ...h,
    approved_at: h.approved_at ?? now,
    created_at: now,
    updated_at: now,
  };
}

